        ("-u, --unwind", "Show the unwind (stack-walking) information.", "Advanced exploit work and debugging."),
        ("-d, --dynamic", "Show the dynamic section: needed libraries, rpath, flags.", "Which libraries does it load?"),
        ("-V, --version-info", "Show version sections (which library versions are required).", "Library compatibility."),
        ("-A, --arch-specific", "Show architecture-specific information.", "ARM, MIPS and other targets."),
        ("-D, --use-dynamic", "Use the dynamic section's own symbol table instead of the section headers.", "Files with broken or stripped section headers."),
        ("-L, --lint, --enable-checks", "Check the file for problems and report them.", "Finding malformed or tampered files."),
        ("-I, --histogram", "Show a histogram of bucket list lengths when printing symbol tables.", "Hash table analysis; rare."),
        ("-n, --notes", "Show the notes sections (build id, ABI tag).", "Identifying an exact build."),
        ("-x, --hex-dump=<number|name>", "Dump a section (by number or name) as hexadecimal bytes.", "Looking at raw data tables."),
        ("-p, --string-dump=<number|name>", "Dump a section as readable strings.", "Reading .rodata and .comment."),
        ("-R, --relocated-dump=<number|name>", "Dump a section as bytes after relocations are applied.", "Seeing final contents of data."),
        ("-z, --decompress", "Decompress sections before dumping them.", "Compressed debug sections."),
        ("-w, --debug-dump[=...]", "Dump debugging information (DWARF): line numbers, info, macros and more.", "Programs compiled with -g."),
