        ("--ctf[=section], --ctf-symbols=section, --ctf-strings=section, --ctf-parent=name", "Dump Compact C Type Format data and tell readelf where to find its symbols, strings and parent.", "Rare."),
        ("-c, --archive-index", "Show the symbol index of an archive (.a library).", "Looking inside static libraries."),
